policies.schema:
// Fragment of a Jira MCP server: one namespace, the server's own. Base types (User, ResourceScope, RequestContext) are
// referenced unqualified from the empty namespace of cedar/mcp.cedarschema. Every entity type has `scopes`.

namespace Jira {
  entity Project {
    key: String,
    // Classification: required, "" when the project has no category. The entity builder normalizes it (trim, ASCII lower
    // case); the canonical value for restricted data is "restricted".
    category: String,
    scopes: Set<ResourceScope>,
  };
  // `project` duplicates the parent edge because Cedar cannot read attributes of an ancestor through `in`.
  entity Issue in [Project] {
    key: String,
    project: Project,
    scopes: Set<ResourceScope>,
  };

  action "read", "update", "delete", "admin" appliesTo {
    principal: [User],
    resource: [Project, Issue],
    context: RequestContext,
  };
}

files.text:
// Data classified as restricted is never available to AI agents, whatever the user may do in Jira. forbid overrides every
// permit, so no group or scope can open it.

@id("jira-forbid-restricted-project")
forbid (principal, action, resource is Jira::Project)
when { resource.category == "restricted" };

@id("jira-forbid-restricted-issue")
forbid (principal, action, resource is Jira::Issue)
when { resource.project.category == "restricted" };

// Reading follows the user's own rights in Jira; the server adds the group check and the classification rule.

@id("jira-read")
permit (
  principal in UserGroup::"mcp-jira-read",
  action == Jira::Action::"read",
  resource
)
when { resource is Jira::Project || resource is Jira::Issue };

// Changes only inside the projects granted by the scope mapping. `principal in resource.scopes` is true when one of the
// user's groups is mapped to the resource scope; an issue carries the scope of its project.

@id("jira-update-project-in-scope")
permit (
  principal in UserGroup::"mcp-jira-write",
  action == Jira::Action::"update",
  resource is Jira::Project
)
when { principal in resource.scopes };

@id("jira-update-issue-in-scope")
permit (
  principal in UserGroup::"mcp-jira-write",
  action == Jira::Action::"update",
  resource is Jira::Issue
)
when { principal in resource.scopes };

@id("jira-delete-issue-in-scope")
permit (
  principal in UserGroup::"mcp-jira-destructive",
  action == Jira::Action::"delete",
  resource is Jira::Issue
)
when { principal in resource.scopes };
